// Example: generated types + zod usage
import { createZodFromOutputSchema, parseStreamingStructuredOutput } from '@redwood-inference/ts-sdk';
const z = createZodFromOutputSchema(require('./specs/reply-spec.json'));
// in a streaming handler:
for await (const chunk of responseStream) {
  const res = await parseStreamingStructuredOutput(chunk, z);
  if (res.status === 'complete') {
    // TypeScript will narrow based on discriminator
    if (res.value.type === 'tool') {
      // tool-specific fields available here
    }
  }
}

